-- Check: sample records per register (10 each).
SELECT l.register_key, count(r.id) AS records
FROM public.local_registers l
LEFT JOIN public.local_register_records r ON r.register_id = l.id AND r.is_deleted = FALSE
WHERE l.id IN ('00000000-0000-4000-9003-00000000001a'::uuid, '00000000-0000-4000-9003-00000000001b'::uuid, '00000000-0000-4000-9003-00000000001c'::uuid, '00000000-0000-4000-9003-00000000001d'::uuid, '00000000-0000-4000-9003-00000000001e'::uuid, '00000000-0000-4000-9003-00000000001f'::uuid)
GROUP BY l.register_key ORDER BY l.register_key;
